// @vegastack email-kit@0.25.2 sha256-XShlr39IsZ7tbF8fGC61VayE+nWywl9L9+27FzLc1OA=

/**
 * GENERATED by `tooling/generate-email-tokens.mjs` from `packages/design-tokens/tokens/*.json`.
 * Do not edit: change the tokens (or the generator's role map) and run
 * `node tooling/generate-email-tokens.mjs`. `design:verify` fails when this file is stale.
 *
 * The email kit's colours as sRGB hex — email clients read neither CSS variables nor OKLCH. Pure
 * white and black are nudged one step (#fffffe / #010101) so Gmail's forced dark inversion leaves
 * them alone, and every text/background pair below is AA (4.5:1) in both modes.
 */

/** One mode's email palette. */
export interface EmailPalette {
  /** The page behind the card. */
  canvas: string;
  /** The card the message sits on. */
  surface: string;
  /** Headings and body copy. */
  text: string;
  /** Secondary copy: meta, times, the footer. */
  muted: string;
  /** Card and divider hairlines. */
  border: string;
  /** The button fill. */
  buttonBg: string;
  /** The button label. */
  buttonText: string;
  /** A quoted comment's background. */
  quoteBg: string;
  /** A quoted comment's leading bar. */
  quoteBar: string;
}

/** Light and dark palettes, resolved from the design tokens. */
export const emailColors: { light: EmailPalette; dark: EmailPalette } = {
  light: {
    canvas: "#fafafa",
    surface: "#fffffe",
    text: "#0a0a0a",
    muted: "#6e6e6e",
    border: "#e5e5e5",
    buttonBg: "#171717",
    buttonText: "#fafafa",
    quoteBg: "#f5f5f5",
    quoteBar: "#e5e5e5",
  },
  dark: {
    canvas: "#0a0a0a",
    surface: "#171717",
    text: "#fafafa",
    muted: "#a1a1a1",
    border: "#2e2e2e",
    buttonBg: "#e5e5e5",
    buttonText: "#171717",
    quoteBg: "#262626",
    quoteBar: "#474747",
  },
};

/** The system font stack — web fonts do not load in Gmail or Outlook. */
export const emailFontFamily =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";

/**
 * The dark-mode and phone-width `<style>` block: `prefers-color-scheme` for the clients that
 * honour it, and tighter gutters with a full-width button under 600px. Elements opt in with the
 * `vs-*` class hooks.
 */
export const emailCss =
  "@media (prefers-color-scheme:dark){.vs-canvas{background-color:#0a0a0a !important;color:#fafafa !important}.vs-surface{background-color:#171717 !important}.vs-text{color:#fafafa !important}.vs-muted{color:#a1a1a1 !important}.vs-border{border-color:#2e2e2e !important}.vs-quote{background-color:#262626 !important}.vs-quote-bar{border-color:#474747 !important}.vs-rule{border-top-color:#2e2e2e !important}.vs-button{background-color:#e5e5e5 !important;border-color:#e5e5e5 !important;color:#171717 !important}}@media only screen and (max-width:599px){.vs-gutter{padding-left:16px !important;padding-right:16px !important}.vs-pad{padding-left:20px !important;padding-right:20px !important}.vs-button{display:block !important}}";

/**
 * The Outlook.com and new Outlook dark-mode block (`[data-ogsc]` / `[data-ogsb]`), in its own
 * `<style>` so a client that rejects attribute selectors cannot take the media block down with it.
 */
export const emailOutlookCss =
  ".vs-canvas[data-ogsc],.vs-canvas[data-ogsb]{background-color:#0a0a0a !important;color:#fafafa !important}[data-ogsc] .vs-canvas{background-color:#0a0a0a !important;color:#fafafa !important}[data-ogsc] .vs-surface{background-color:#171717 !important}[data-ogsc] .vs-text{color:#fafafa !important}[data-ogsc] .vs-muted{color:#a1a1a1 !important}[data-ogsc] .vs-border{border-color:#2e2e2e !important}[data-ogsc] .vs-quote{background-color:#262626 !important}[data-ogsc] .vs-quote-bar{border-color:#474747 !important}[data-ogsc] .vs-rule{border-top-color:#2e2e2e !important}[data-ogsc] .vs-button{background-color:#e5e5e5 !important;border-color:#e5e5e5 !important;color:#171717 !important}[data-ogsb] .vs-canvas{background-color:#0a0a0a !important;color:#fafafa !important}[data-ogsb] .vs-surface{background-color:#171717 !important}[data-ogsb] .vs-text{color:#fafafa !important}[data-ogsb] .vs-muted{color:#a1a1a1 !important}[data-ogsb] .vs-border{border-color:#2e2e2e !important}[data-ogsb] .vs-quote{background-color:#262626 !important}[data-ogsb] .vs-quote-bar{border-color:#474747 !important}[data-ogsb] .vs-rule{border-top-color:#2e2e2e !important}[data-ogsb] .vs-button{background-color:#e5e5e5 !important;border-color:#e5e5e5 !important;color:#171717 !important}";

// @vegastack email-kit@0.25.2 sha256-XShlr39IsZ7tbF8fGC61VayE+nWywl9L9+27FzLc1OA=

/**
 * Classic Outlook (the Word engine) ignores `max-width`, so a fluid 600px column fills its whole
 * reading pane. The fix is a fixed-width "ghost" table that only Outlook sees, written as
 * conditional comments — which React cannot render. The layout places these two empty markers
 * around its container instead, and `renderEmail` swaps each for its conditional comment.
 */
export const MSO_OPEN = { "data-vs-mso": "open" } as const;
/** The closing marker; see `MSO_OPEN`. */
export const MSO_CLOSE = { "data-vs-mso": "close" } as const;

/**
 * Replace the layout's markers with the Outlook-only 600px ghost table. `renderEmail` calls it;
 * call it yourself only if you render with react-email's `render` directly.
 *
 * @example
 * const html = applyMsoGhostTable(await render(<NotificationEmail {...props} />));
 */
export function applyMsoGhostTable(html: string): string {
  return html
    .replace(
      '<span data-vs-mso="open"></span>',
      '<!--[if mso]><table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0"><tr><td><![endif]-->',
    )
    .replace(
      '<span data-vs-mso="close"></span>',
      "<!--[if mso]></td></tr></table><![endif]-->",
    );
}

// @vegastack email-kit@0.25.2 sha256-XShlr39IsZ7tbF8fGC61VayE+nWywl9L9+27FzLc1OA=

import type { ReactNode } from "react";
import {
  Container,
  Head,
  Html,
  Link,
  Preview,
  Section,
  Text,
} from "react-email";

import {
  emailColors,
  emailCss,
  emailFontFamily,
  emailOutlookCss,
} from "./email-tokens";
import { MSO_CLOSE, MSO_OPEN } from "./mso";

const c = emailColors.light;

/** The product or workspace the email comes from, shown as a text wordmark at the top. */
export interface EmailBrand {
  /** The wordmark text — the product or workspace name. No logo image is used. */
  name: string;
  /** Where the wordmark links; omit for plain text. */
  url?: string;
}

/** One footer link, e.g. "Manage notifications". */
export interface EmailFooterLink {
  /** Descriptive link text — never "click here". */
  label: string;
  /** Absolute URL. */
  href: string;
}

/** The footer under the card: why the person got this, what they can do about it, who sent it. */
export interface EmailFooter {
  /** Why the recipient got this email, e.g. "You're getting this because you're assigned to this task." */
  reason?: string;
  /** Preference and unsubscribe links, shown in one row. */
  links?: EmailFooterLink[];
  /**
   * The closing line: text, or inline content such as text with a `Link` from `react-email`.
   * `null` hides it.
   * @default "Sent with VegaStack"
   */
  note?: ReactNode | null;
  /**
   * Absolute URL that links the note. On the default note only the word "VegaStack" is linked
   * ("Sent with [VegaStack]"); on a string note the whole line is. Ignored when `note` is an
   * element (link inside it instead) or `null`.
   * @default undefined
   */
  noteHref?: string;
}

/** Props for `EmailLayout`. */
export interface EmailLayoutProps {
  /** The wordmark at the top of the email. */
  brand: EmailBrand;
  /** The inbox preview line (preheader), at most ~150 characters. Hidden in the body and the plain-text part. */
  preview: string;
  /**
   * The document `<title>`; some clients show it in a browser view.
   * @default preview
   */
  title?: string;
  /**
   * The language of the email, set on `<html>` and `<body>`.
   * @default "en"
   */
  lang?: string;
  /**
   * Text direction.
   * @default "ltr"
   */
  dir?: "ltr" | "rtl";
  /**
   * The footer under the card.
   * @default undefined
   */
  footer?: EmailFooter;
  /** The card's content — compose the parts from `email-parts`. */
  children: ReactNode;
}

/**
 * The shell every VegaStack email renders in: `<html lang>`, the `color-scheme` metas, a hidden
 * preheader, a text wordmark, one 600px fluid card on a canvas, and the footer. Light colours are
 * inline; dark mode comes from one `<style>` block (`prefers-color-scheme` plus the Outlook.com
 * `[data-ogsc]`/`[data-ogsb]` hooks). Server-safe — render it with `renderEmail`.
 *
 * @example
 * <EmailLayout
 *   brand={{ name: "Acme", url: "https://acme.example" }}
 *   preview="Priya commented on Fix login"
 *   footer={{ reason: "You're getting this because you follow this task." }}
 * >
 *   <EmailHeading>Priya commented on Fix login</EmailHeading>
 * </EmailLayout>
 */
export function EmailLayout({
  brand,
  preview,
  title,
  lang = "en",
  dir = "ltr",
  footer,
  children,
}: EmailLayoutProps) {
  const isDefaultNote = footer?.note === undefined;
  const noteText = isDefaultNote ? "Sent with VegaStack" : footer?.note;
  const noteHref = footer?.noteHref;
  const footerLinkStyle = {
    color: c.muted,
    textDecoration: "underline",
    textDecorationLine: "underline",
  };
  const note =
    noteHref && isDefaultNote ? (
      <>
        Sent with{" "}
        <Link href={noteHref} className="vs-muted" style={footerLinkStyle}>
          VegaStack
        </Link>
      </>
    ) : noteHref && typeof noteText === "string" && noteText ? (
      <Link href={noteHref} className="vs-muted" style={footerLinkStyle}>
        {noteText}
      </Link>
    ) : (
      noteText
    );
  const links = footer?.links ?? [];
  const wordmarkStyle = {
    color: c.text,
    fontFamily: emailFontFamily,
    fontSize: "16px",
    fontWeight: 600,
    lineHeight: "24px",
    textDecoration: "none",
    textDecorationLine: "none",
  };
  const footerText = {
    color: c.muted,
    fontFamily: emailFontFamily,
    fontSize: "13px",
    lineHeight: "20px",
    margin: "0 0 8px",
  };
  return (
    <Html lang={lang} dir={dir}>
      <Head>
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta name="color-scheme" content="light dark" />
        <meta name="supported-color-schemes" content="light dark" />
        <title>{title ?? preview}</title>
        <style dangerouslySetInnerHTML={{ __html: emailCss }} />
        <style dangerouslySetInnerHTML={{ __html: emailOutlookCss }} />
      </Head>
      <body
        lang={lang}
        dir={dir}
        className="vs-canvas"
        style={{
          backgroundColor: c.canvas,
          margin: 0,
          padding: 0,
          WebkitTextSizeAdjust: "100%",
        }}
      >
        <Preview useTitleTag={false}>{preview}</Preview>
        {/* The canvas is a full-width table cell, not just <body>: several clients drop body styles. */}
        <Section
          className="vs-canvas"
          style={{
            backgroundColor: c.canvas,
            color: c.text,
            fontFamily: emailFontFamily,
          }}
        >
          {/* Classic Outlook ignores max-width: renderEmail swaps these markers for a 600px ghost table. */}
          <span {...MSO_OPEN} />
          <Container
            tdClassName="vs-gutter"
            style={{
              maxWidth: "600px",
              width: "100%",
              margin: "0 auto",
              padding: "32px 24px",
            }}
          >
            <Section style={{ padding: "0 4px 16px" }}>
              <Text className="vs-text" style={{ ...wordmarkStyle, margin: 0 }}>
                {brand.url ? (
                  <Link
                    href={brand.url}
                    className="vs-text"
                    style={wordmarkStyle}
                  >
                    {brand.name}
                  </Link>
                ) : (
                  brand.name
                )}
              </Text>
            </Section>
            <Section
              className="vs-surface vs-border"
              tdClassName="vs-pad"
              style={{
                backgroundColor: c.surface,
                border: `1px solid ${c.border}`,
                borderRadius: "12px",
                borderCollapse: "separate",
                padding: "32px",
              }}
            >
              {children}
            </Section>
            {footer?.reason || links.length > 0 || note ? (
              <Section style={{ padding: "24px 4px 0" }}>
                {footer?.reason ? (
                  <Text className="vs-muted" style={footerText}>
                    {footer.reason}
                  </Text>
                ) : null}
                {links.length > 0 ? (
                  <Text className="vs-muted" style={footerText}>
                    {links.map((link, index) => (
                      <span key={link.href}>
                        {index > 0 ? " · " : null}
                        <Link
                          href={link.href}
                          className="vs-muted"
                          style={footerLinkStyle}
                        >
                          {link.label}
                        </Link>
                      </span>
                    ))}
                  </Text>
                ) : null}
                {note ? (
                  <Text className="vs-muted" style={footerText}>
                    {note}
                  </Text>
                ) : null}
              </Section>
            ) : null}
          </Container>
          <span {...MSO_CLOSE} />
        </Section>
      </body>
    </Html>
  );
}

// @vegastack email-kit@0.25.2 sha256-XShlr39IsZ7tbF8fGC61VayE+nWywl9L9+27FzLc1OA=

import { Fragment } from "react";
import type { ReactNode } from "react";
import { Button, Heading, Hr, Link, Section, Text } from "react-email";

import { emailColors, emailFontFamily } from "./email-tokens";

const c = emailColors.light;
// Set on every text element: classic Outlook does not reliably inherit a font through tables.
const font = emailFontFamily;

/** Props for `EmailHeading`. */
export interface EmailHeadingProps {
  /** The heading text — for a notification, the event sentence ("Priya commented on Fix login"). */
  children: ReactNode;
  /**
   * The heading level. One `h1` per email; `h2` for a section inside it.
   * @default "h1"
   */
  as?: "h1" | "h2";
}

/**
 * The email's heading: 20px semibold for `h1`, 16px for `h2`.
 *
 * @example
 * <EmailHeading>Priya commented on Fix login</EmailHeading>
 */
export function EmailHeading({ children, as = "h1" }: EmailHeadingProps) {
  const h1 = as === "h1";
  return (
    <Heading
      as={as}
      className="vs-text"
      style={{
        color: c.text,
        fontFamily: font,
        fontSize: h1 ? "20px" : "16px",
        fontWeight: 600,
        lineHeight: h1 ? "28px" : "24px",
        margin: h1 ? "0 0 12px" : "24px 0 8px",
      }}
    >
      {children}
    </Heading>
  );
}

/** Props for `EmailText`. */
export interface EmailTextProps {
  /** The paragraph. Inline `EmailLink`s are fine inside it. */
  children: ReactNode;
  /**
   * `muted` for secondary copy — an expiry note, a "you can ignore this" line.
   * @default "default"
   */
  tone?: "default" | "muted";
}

/**
 * A body paragraph, 15px on a 24px line.
 *
 * @example
 * <EmailText>Anand assigned you to Fix login in Acme.</EmailText>
 */
export function EmailText({ children, tone = "default" }: EmailTextProps) {
  const muted = tone === "muted";
  return (
    <Text
      className={muted ? "vs-muted" : "vs-text"}
      style={{
        color: muted ? c.muted : c.text,
        fontFamily: font,
        fontSize: muted ? "14px" : "15px",
        lineHeight: muted ? "22px" : "24px",
        margin: "0 0 16px",
      }}
    >
      {children}
    </Text>
  );
}

/** Props for `EmailLink`. */
export interface EmailLinkProps {
  /** Absolute URL. */
  href: string;
  /** Descriptive text that says where the link goes — never "click here". */
  children: ReactNode;
}

/**
 * An underlined inline link in the text colour.
 *
 * @example
 * <EmailText>
 *   Or open <EmailLink href="https://acme.example/tasks/42">Fix login</EmailLink>.
 * </EmailText>
 */
export function EmailLink({ href, children }: EmailLinkProps) {
  return (
    <Link
      href={href}
      className="vs-text"
      style={{
        color: c.text,
        textDecoration: "underline",
        textDecorationLine: "underline",
      }}
    >
      {children}
    </Link>
  );
}

/** Props for `EmailButton`. */
export interface EmailButtonProps {
  /** Absolute URL the button opens. */
  href: string;
  /** The action, verb first: "View comment", "Open page", "Review request". */
  children: ReactNode;
}

/**
 * The one call to action: a bulletproof link button (padding Outlook understands, no image), at
 * least 44px tall, full width on a phone.
 *
 * @example
 * <EmailButton href="https://acme.example/tasks/42#comment-7">View comment</EmailButton>
 */
export function EmailButton({ href, children }: EmailButtonProps) {
  return (
    <Section style={{ padding: "8px 0 8px" }}>
      <Button
        href={href}
        className="vs-button"
        style={{
          backgroundColor: c.buttonBg,
          border: `1px solid ${c.buttonBg}`,
          borderRadius: "8px",
          color: c.buttonText,
          fontFamily: font,
          fontSize: "15px",
          fontWeight: 600,
          padding: "13px 24px",
          textAlign: "center",
        }}
      >
        {children}
      </Button>
    </Section>
  );
}

/** One label/value row on an `EmailCard`. */
export interface EmailCardMeta {
  /** The field name: "Status", "Due", "Space". */
  label: string;
  /** The value, already formatted ("Fri 9 Oct, 10:00 IST"). */
  value: string;
}

/** Props for `EmailCard`. */
export interface EmailCardProps {
  /** The record's title. */
  title: string;
  /**
   * Link for the title; omit for plain text.
   * @default undefined
   */
  href?: string;
  /**
   * Label/value rows under the title.
   * @default []
   */
  meta?: EmailCardMeta[];
  /**
   * Extra content under the meta rows.
   * @default undefined
   */
  children?: ReactNode;
}

/**
 * A summary of the record the email is about: its title (linked) and a few label/value rows.
 *
 * @example
 * <EmailCard
 *   title="Fix login"
 *   href="https://acme.example/tasks/42"
 *   meta={[{ label: "Due", value: "Fri 9 Oct, 10:00 IST" }]}
 * />
 */
export function EmailCard({
  title,
  href,
  meta = [],
  children,
}: EmailCardProps) {
  const titleStyle = {
    color: c.text,
    fontFamily: font,
    fontSize: "15px",
    fontWeight: 600,
    lineHeight: "22px",
  };
  return (
    <Section
      className="vs-border"
      style={{
        border: `1px solid ${c.border}`,
        borderRadius: "8px",
        borderCollapse: "separate",
        margin: "0 0 16px",
        padding: "16px",
      }}
    >
      <Text className="vs-text" style={{ ...titleStyle, margin: 0 }}>
        {href ? (
          <Link
            href={href}
            className="vs-text"
            style={{
              ...titleStyle,
              textDecoration: "underline",
              textDecorationLine: "underline",
            }}
          >
            {title}
          </Link>
        ) : (
          title
        )}
      </Text>
      {meta.map((row) => (
        <Text
          key={row.label}
          className="vs-muted"
          style={{
            color: c.muted,
            fontFamily: font,
            fontSize: "13px",
            lineHeight: "20px",
            margin: "4px 0 0",
          }}
        >
          {row.label}:{" "}
          <span className="vs-text" style={{ color: c.text }}>
            {row.value}
          </span>
        </Text>
      ))}
      {children}
    </Section>
  );
}

/** Props for `EmailQuote`. */
export interface EmailQuoteProps {
  /**
   * Who wrote it.
   * @default undefined
   */
  author?: string;
  /**
   * When, already formatted with its zone ("Fri 9 Oct, 10:00 IST").
   * @default undefined
   */
  time?: string;
  /** The quoted text, as plain text. Each line break becomes a `<br>` (and a line in the plain-text part). */
  body: string;
}

/**
 * A quoted comment or message: a tinted block with a leading bar, the author and time above.
 *
 * @example
 * <EmailQuote author="Priya" time="Fri 9 Oct, 10:00 IST" body="Can we ship this by Friday?" />
 */
export function EmailQuote({ author, time, body }: EmailQuoteProps) {
  return (
    <Section
      className="vs-quote vs-quote-bar"
      style={{
        backgroundColor: c.quoteBg,
        borderLeft: `3px solid ${c.quoteBar}`,
        borderRadius: "4px",
        margin: "0 0 16px",
        padding: "12px 16px",
      }}
    >
      {author || time ? (
        <Text
          className="vs-muted"
          style={{
            color: c.muted,
            fontFamily: font,
            fontSize: "13px",
            lineHeight: "20px",
            margin: "0 0 4px",
          }}
        >
          {author ? (
            <strong className="vs-text" style={{ color: c.text }}>
              {author}
            </strong>
          ) : null}
          {author && time ? " · " : null}
          {time}
        </Text>
      ) : null}
      <Text
        className="vs-text"
        style={{
          color: c.text,
          fontFamily: font,
          fontSize: "15px",
          lineHeight: "24px",
          margin: 0,
        }}
      >
        {/* Explicit breaks: classic Outlook ignores white-space, and the plain-text part needs them. */}
        {body.split(/\r?\n/).map((line, index) => (
          <Fragment key={index}>
            {index > 0 ? <br /> : null}
            {line}
          </Fragment>
        ))}
      </Text>
    </Section>
  );
}

/** One row in an `EmailItems` group. */
export interface EmailItem {
  /** Who did it — a person, or the agent's name. Omit for system events. */
  actor?: string;
  /** What happened, after the actor: "commented on Fix login". */
  text: string;
  /** Where the row links. */
  href?: string;
  /** When, already formatted ("10:00 IST"). */
  time?: string;
}

/** A titled group of rows, e.g. one record or one day. */
export interface EmailItemGroup {
  /** The group heading: a record title or "Due today". */
  title: string;
  /** The rows. */
  items: EmailItem[];
}

/** Props for `EmailItems`. */
export interface EmailItemsProps {
  /** The groups, in order. */
  groups: EmailItemGroup[];
}

/**
 * The digest list: groups with a heading, each row "**Actor** did something" with its time.
 *
 * @example
 * <EmailItems
 *   groups={[
 *     {
 *       title: "Fix login",
 *       items: [{ actor: "Priya", text: "commented", href: "https://acme.example/tasks/42", time: "10:00 IST" }],
 *     },
 *   ]}
 * />
 */
export function EmailItems({ groups }: EmailItemsProps) {
  return (
    <>
      {groups.map((group, groupIndex) => (
        <Section
          key={`${group.title}-${groupIndex}`}
          style={{ margin: groupIndex === 0 ? "0" : "16px 0 0" }}
        >
          <Heading
            as="h2"
            className="vs-text"
            style={{
              color: c.text,
              fontFamily: font,
              fontSize: "14px",
              fontWeight: 600,
              lineHeight: "20px",
              margin: "0 0 4px",
            }}
          >
            {group.title}
          </Heading>
          {group.items.map((item, index) => {
            const sentence = item.actor ? (
              <>
                <strong>{item.actor}</strong> {item.text}
              </>
            ) : (
              item.text
